class WebsiteHandler(BaseHTTPRequestHandler):
    """Serve the game page and ephemeral LAN race room API."""

    def do_GET(self) -> None:  # noqa: N802
        parsed = urlparse(self.path)
        if parsed.path == "/api/race/room":
            query = parse_qs(parsed.query)
            code = query.get("code", [""])[0].upper()
            player_id = query.get("player", [""])[0]
            with ROOM_LOCK:
                room = ROOMS.get(code)
                if not room or player_id not in room["players"]:
                    self._json({"error": "Room or player not found."}, 404)
                    return
                room["players"][player_id]["last_seen"] = time.time()
                self._json({"room": self._public_room(room)})
            return
        body = PAGE.encode("utf-8")
        self.send_response(200)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self) -> None:  # noqa: N802
        try:
            length = min(int(self.headers.get("Content-Length", "0")), 20_000)
            data = json.loads(self.rfile.read(length) or b"{}")
            path = urlparse(self.path).path
            if path == "/api/race/join":
                with ROOM_LOCK:
                    action = data.get("action")
                    code = str(data.get("code", "")).strip().upper()
                    if action == "create":
                        now = time.time()
                        for old_code, old_room in list(ROOMS.items()):
                            if now - old_room.get("last_active", old_room["created"]) > 6 * 60 * 60:
                                ROOMS.pop(old_code, None)
                        if len(ROOMS) >= 100:
                            self._json({"error": "The room service is busy. Try again shortly."}, 503)
                            return
                        code = "".join(random.choices("ABCDEFGHJKLMNPQRSTUVWXYZ23456789", k=6))
                        ROOMS[code] = {"players": {}, "race": None, "created": now, "last_active": now}
                    elif action != "join" or code not in ROOMS:
                        self._json({"error": "That room code was not found."}, 404)
                        return
                    room = ROOMS[code]
                    if room["race"]:
                        self._json({"error": "That race has already started."}, 409)
                        return
                    if len(room["players"]) >= 12:
                        self._json({"error": "This room already has 12 agents."}, 409)
                        return
                    name = " ".join(str(data.get("name", "Agent")).split())[:24] or "Agent"
                    player_id = secrets.token_urlsafe(12)
                    xp = max(0, min(int(data.get("xp", 0)), 4900))
                    rank = str(data.get("rank", "Bronze I"))[:32]
                    level = min(50, xp // 100 + 1)
                    seen = [x for x in data.get("seen", []) if isinstance(x, str)][:1000]
                    room["players"][player_id] = {"id": player_id, "name": name, "rank": rank, "level": level, "xp": xp, "score": 0, "index": 0, "finished": False, "seen": set(seen), "last_seen": time.time()}
                    self._json({"code": code, "player": player_id, "room": self._public_room(room)})
                return
            if path == "/api/race/start":
                with ROOM_LOCK:
                    room = ROOMS.get(str(data.get("code", "")).upper())
                    if not room or data.get("player") not in room["players"]:
                        self._json({"error": "Room or player not found."}, 404)
                        return
                    if len(room["players"]) < 2:
                        self._json({"error": "Invite at least one other agent before starting."}, 409)
                        return
                    if not room["race"]:
                        seen = set().union(*(p["seen"] for p in room["players"].values()))
                        available = [sid for sid in SCENARIO_IDS if sid not in seen]
                        if not available:
                            self._json({"error": "Everyone has seen all current scenarios. Add new cards to the scenario library to race again."}, 409)
                            return
                        questions = random.sample(available, min(8, len(available)))
                        room["race"] = {"started": time.time(), "endsAt": time.time() + 90, "questions": questions}
                    self._json({"room": self._public_room(room)})
                return
            if path == "/api/race/progress":
                with ROOM_LOCK:
                    room = ROOMS.get(str(data.get("code", "")).upper())
                    player = room["players"].get(data.get("player")) if room else None
                    if not room or not player or not room["race"]:
                        self._json({"error": "Race session not found."}, 404)
                        return
                    player["index"] = max(player["index"], min(int(data.get("index", 0)), len(room["race"]["questions"])))
                    player["score"] = max(player["score"], min(int(data.get("score", 0)), player["index"]))
                    player["finished"] = bool(data.get("finished")) or player["index"] >= len(room["race"]["questions"]) or time.time() >= room["race"]["endsAt"]
                    player["last_seen"] = time.time()
                    self._json({"room": self._public_room(room)})
                return
            self._json({"error": "Unknown race endpoint."}, 404)
        except (ValueError, TypeError, json.JSONDecodeError):
            self._json({"error": "Invalid race request."}, 400)

    def _public_room(self, room: dict) -> dict:
        players = []
        now = time.time()
        room["last_active"] = now
        for player in room["players"].values():
            players.append({key: player[key] for key in ("id", "name", "rank", "level", "score", "index", "finished")} | {"online": now - player["last_seen"] < 5})
        return {"players": players, "race": room["race"], "serverNow": now}

    def _json(self, value: dict, status: int = 200) -> None:
        body = json.dumps(value).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        self.wfile.write(body)

    def log_message(self, format: str, *args: object) -> None:
        print(f"[{self.log_date_time_string()}] {format % args}")


def main() -> None:
    server = ThreadingHTTPServer((HOST, PORT), WebsiteHandler)
    print(f"Signal//Safe running locally at http://127.0.0.1:{PORT} (press Ctrl+C to stop)")
    addresses = sorted({item[4][0] for item in socket.getaddrinfo(socket.gethostname(), None, socket.AF_INET) if not item[4][0].startswith("127.")})
    for address in addresses:
        print(f"LAN multiplayer address: http://{address}:{PORT}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        print("\nShutting down game.")
    finally:
        server.server_close()


if __name__ == "__main__":
    main()
